args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?composer ?composerLabel ?deathDate WHERE {
  dbr:The_Sparrow's_Fluttering dbo:musicComposer ?composer .
  OPTIONAL { ?composer dbo:deathDate ?d1 . }
  OPTIONAL { ?composer dbp:deathDate ?d2 . }
  BIND(COALESCE(?d1, ?d2) AS ?deathDate)
  OPTIONAL { ?composer rdfs:label ?composerLabel . FILTER(langMatches(lang(?composerLabel), "en")) }
}

